# -*- coding: utf-8 -*-
import sys
import os
sys.path.append(os.path.dirname(__file__))
from task_builder import format_task, save_file

tasks_data = [(101, "Oddiy qo'shish va ayirish: '$(( ... ))'", "Serverdagi mavjud va yangi qo'shilgan xotira hajmlarini hisoblang.", '#!/usr/bin/env bash\n\nbase_mem=8\nadditional_mem=16\ntotal_mem=$((base_mem + additional_mem))\nused_mem=$((total_mem - 4))\n\necho "Umumiy xotira: ${total_mem}GB, Band: ${used_mem}GB"\n', "Bash-da arifmetik hisob-kitoblar '$(( ifoda ))' sintaksisi orqali bajariladi. Qavslar ichida o'zgaruvchilar oldiga '$' qo'yish shart emas.", 'Umumiy xotira: 24GB, Band: 20GB'), (102, "Ko'paytirish va butunli bo'lish amallari", "Server klasteridagi jami protsessor yadrolarini va o'rtacha taqsimotni hisoblang.", '#!/usr/bin/env bash\n\nservers=6\ncores_per_server=8\ntotal_cores=$((servers * cores_per_server))\nservices=5\ncores_per_service=$((total_cores / services))\n\necho "Jami yadrolar: $total_cores, Servis boshiga: $cores_per_service"\n', "Bash-da butunli bo'lish ('/') faqat butun qismini qaytaradi, qoldiq tashlab yuboriladi.", 'Jami yadrolar: 48, Servis boshiga: 9'), (103, "Qoldiq (modul) amali: '%' operatori", 'Berilgan sonning juft yoki toq ekanligini qoldiq orqali aniqlang.', '#!/usr/bin/env bash\n\nnumber=42\nremainder=$((number % 2))\n\nif [ $remainder -eq 0 ]; then\n    echo "$number - Juft son"\nelse\n    echo "$number - Toq son"\nfi\n', "'%' operatori butun sonli bo'lishdagi qoldiqni qaytaradi. Sonni 2 ga bo'lgandagi qoldiq 0 bo'lsa juft, 1 bo'lsa toq bo'ladi.", '42 - Juft son'), (104, "Darajaga ko'tarish: '**' operatori", '2 ning 10-darajasini (1 Kilobayt baytlarda) hisoblang.', '#!/usr/bin/env bash\n\npower=$((2 ** 10))\necho "2 ning 10-darajasi: $power bayt"\n', "'**' operatori asosni ko'rsatilgan darajaga ko'taradi.", '2 ning 10-darajasi: 1024 bayt'), (105, 'Inkrement: Post-increment vs Pre-increment', "Inkrement operatorlarining ('i++' va '++i') qiymat qaytarish tartibini solishtiring.", '#!/usr/bin/env bash\n\ni=5\nval1=$((i++))\necho "val1 (i++): $val1, joriy i: $i"\n\nj=5\nval2=$((++j))\necho "val2 (++j): $val2, joriy j: $j"\n', "'i++' (post-inkrement) avval joriy qiymatni qaytaradi, so'ng o'zgaruvchini oshiradi. '++i' (pre-inkrement) esa avval oshiradi, so'ng yangi qiymatni qaytaradi.", 'val1 (i++): 5, joriy i: 6\nval2 (++j): 6, joriy j: 6'), (106, 'Dekrement: Post-decrement va Pre-decrement', "Qiymatni kamaytirish operatorlarining ('i--' va '--i') ishlashini ko'rsating.", '#!/usr/bin/env bash\n\ncount=10\necho "Post-dekrement: $((count--)), yangi count: $count"\necho "Pre-dekrement: $((--count)), yangi count: $count"\n', "'count--' va '--count' o'zgaruvchi qiymatini 1 taga kamaytiradi.", 'Post-dekrement: 10, yangi count: 9\nPre-dekrement: 8, yangi count: 8'), (107, "Qisqartirilgan biriktirishlar: '+=', '-=', '*=', '/='", "O'zgaruvchini qisqa operatorlar yordamida yangilang.", '#!/usr/bin/env bash\n\nbalance=100\nbalance+=50\nbalance-=20\nbalance*=2\nbalance/=4\n\necho "Yakuniy hisob: $balance"\n', "Arifmetik blok ichida 'x += y' amali 'x = x + y' amali bilan bir xil natijani beradi.", 'Yakuniy hisob: 65'), (108, "'let' buyrug'i yordamida arifmetika", "Maxsus 'let' buyrug'i yordamida arifmetik ifodani hisoblang.", '#!/usr/bin/env bash\n\nlet "sum = 25 + 75"\nlet "sum += 10"\n\necho "Yig\'indi: $sum"\n', "'let' Bash-ning ichki buyrug'i bo'lib, berilgan arifmetik ifodalarni baholaydi va natijani o'zgaruvchiga yozadi.", "Yig'indi: 110"), (109, "Bir nechta amalni 'let' bilan bitta qatorda bajarish", "Bir nechta o'zgaruvchini bitta 'let' orqali hisoblang.", '#!/usr/bin/env bash\n\nlet a=10+2 b=20*3 c=b-a\necho "a=$a, b=$b, c=$c"\n', "'let' probelsiz yoki qo'shtirnoq ichida bir nechta tengliklarni bir qatorda bajarish imkonini beradi.", 'a=12, b=60, c=48'), (110, "'expr' tashqi buyrug'i bilan arifmetika", "Tarixiy POSIX 'expr' utilitasi yordamida sonlarni ko'paytiring.", '#!/usr/bin/env bash\n\nresult=$(expr 7 \\* 8)\necho "Ko\'paytma: $result"\n', "'expr' tashqi utilita bo'lib, har bir operand va operator orasida bo'sh joy bo'lishini talab qiladi. '*' qobiq tomonidan fayl nomi sifatida kengayib ketmasligi uchun '\\*' bilan qochirilishi shart.", "Ko'paytma: 56"), (111, "Arifmetik baholash: '(( ... ))' va uning chiqish statusi", "Arifmetik blokning nol yoki noldan farqli natijasiga ko'ra exit kodini tekshiring.", '#!/usr/bin/env bash\n\n(( 10 > 5 ))\necho "10 > 5 statusi: $?"\n\n(( 10 == 0 ))\necho "10 == 0 statusi: $?"\n', "'(( ifoda ))' amali rost bo'lsa exit kodi 0 (muvaffaqiyat) bo'ladi, agar natija 0 yoki yolg'on bo'lsa exit kodi 1 bo'ladi.", '10 > 5 statusi: 0\n10 == 0 statusi: 1'), (112, "Arifmetik taqqoslash: '(( a > b ))'", 'Server yuklamasini chegaraviy qiymat bilan solishtiring.', '#!/usr/bin/env bash\n\ncurrent_load=85\nthreshold=80\n\nif (( current_load > threshold )); then\n    echo "DIQQAT: Server yuklamasi normadan oshdi!"\nfi\n', "'(( ))' konstruktsiyasi ichida C tilidagi an'anaviy taqqoslash belgilari ('>', '<', '>=', '<=', '==', '!=') ishlatiladi.", 'DIQQAT: Server yuklamasi normadan oshdi!'), (113, "Tenglik va notenglik: '(( a == b ))' va '(( a != b ))'", 'Xizmat replikalari sonini tekshiring.', '#!/usr/bin/env bash\n\ndesired=3\nactual=3\n\nif (( desired == actual )); then\n    echo "Replikalar soni mos keladi."\nfi\n', "'==' arifmetik tenglikni, '!=' esa notenglikni tekshiradi.", 'Replikalar soni mos keladi.'), (114, "Arifmetikada oraliqni tekshirish: '(( a >= min && a <= max ))'", 'Foydalanuvchi yoshi talab qilingan oraliqda ekanligini bitta shartda tekshiring.', '#!/usr/bin/env bash\n\nage=25\nif (( age >= 18 && age <= 65 )); then\n    echo "Foydalanuvchi ishga layoqatli yoshda."\nfi\n', "'(( ))' ichida mantiqiy '&&' va '||' to'g'ridan-to'g'ri ishlatiladi, qo'shimcha qavslar talab etilmaydi.", 'Foydalanuvchi ishga layoqatli yoshda.'), (115, "Mantiqiy INKOR: '!' arifmetika ichida", 'Son nol emasligini inkor amali bilan tekshiring.', '#!/usr/bin/env bash\n\nerror_count=0\nif (( !error_count )); then\n    echo "Xatolar yo\'q, barchasi toza."\nfi\n', "Arifmetikada 0 yolg'on (false) hisoblanadi. '!0' esa 1 (rost) ga aylanadi.", "Xatolar yo'q, barchasi toza."), (116, "Ternar shart operatori: '(( max = (a > b) ? a : b ))'", 'Ikki sonning kattasini bitta qatorda aniqlang.', '#!/usr/bin/env bash\n\nx=45\ny=78\n(( max = (x > y) ? x : y ))\n\necho "Kattasi: $max"\n', "Bash arifmetikasi C uslubidagi 'shart ? rost : yolg'on' ternar operatorini to'liq qo'llab-quvvatlaydi.", 'Kattasi: 78'), (117, "Bitwise AND ('&') amali va bayroq tekshiruvi", "Ruxsatlar bitmaskida o'qish huquqi (Read bit) mavjudligini aniqlang.", '#!/usr/bin/env bash\n\n# Huquqlar: READ=4 (bit 2), WRITE=2 (bit 1), EXEC=1 (bit 0)\nPERM_READ=4\nuser_perm=6 # READ + WRITE (4 + 2)\n\nif (( (user_perm & PERM_READ) != 0 )); then\n    echo "Foydalanuvchida o\'qish huquqi bor."\nfi\n', "'&' (bitwise AND) amali ikkala operandning bir xil o'rindagi bitlari 1 bo'lgandagina 1 beradi. Bitmask tekshiruvlarida poydevor hisoblanadi.", "Foydalanuvchida o'qish huquqi bor."), (118, "Bitwise OR ('|') amali va bayroqlarni birlashtirish", "Ikki xil ruxsat bayrog'ini bitta butun songa birlashtiring.", '#!/usr/bin/env bash\n\nFLAG_READ=4\nFLAG_EXEC=1\ncombined=$((FLAG_READ | FLAG_EXEC))\n\necho "Birlashgan ruxsat: $combined"\n', "'|' (bitwise OR) kamida bitta operand biti 1 bo'lsa 1 qaytaradi.", 'Birlashgan ruxsat: 5'), (119, "Bitwise XOR ('^') amali yordamida qiymatlarni almashtirish (Swap)", "Qo'shimcha vaqtinchalik o'zgaruvchisiz ikki sonning qiymatini almashtiring.", '#!/usr/bin/env bash\n\na=15\nb=27\n\n(( a = a ^ b ))\n(( b = a ^ b ))\n(( a = a ^ b ))\n\necho "Almashtirilgandan so\'ng: a=$a, b=$b"\n', "'^' (bitwise XOR) turli bitlar uchun 1, bir xil bitlar uchun 0 beradi. Uch karra XOR orqali sonlar xotirasini xavfsiz almashtirish klassik algoritm hisoblanadi.", "Almashtirilgandan so'ng: a=27, b=15"), (120, "Bitwise NOT ('~') inkor amali", "Butun sonning bitlarini teskarisiga o'giring (1-to'ldiruvchi).", '#!/usr/bin/env bash\n\nnum=0\nnot_num=$((~num))\n\necho "0 ning inkor qilingan qiymati: $not_num"\n', "'~' barcha bitlarni teskari qiladi (0->1, 1->0). 2-to'ldiruvchi tizimda '~x' har doim '-(x + 1)' ga teng bo'ladi.", '0 ning inkor qilingan qiymati: -1'), (121, "Chapga bit siljitish ('<<') orqali 2 ga ko'paytirish", "Sonni 3 bit chapga siljitib, uni 8 ga ($2^3$) ko'paytiring.", '#!/usr/bin/env bash\n\nval=5\nshifted=$((val << 3))\n\necho "5 << 3 natijasi: $shifted"\n', "'<< N' amali barcha bitlarni chapga N ta siljitadi, bu sonni 2 ning N-darajasiga ko'paytirish bilan tengdir va protsessorda o'ta tez bajariladi.", '5 << 3 natijasi: 40'), (122, "O'ngga bit siljitish ('>>') orqali 2 ga bo'lish", "64 sonini 2 bit o'ngga siljiting ($64 / 2^2$).", '#!/usr/bin/env bash\n\nval=64\nshifted=$((val >> 2))\n\necho "64 >> 2 natijasi: $shifted"\n', "'>> N' amali bitlarni o'ngga suradi va sonni butunli bo'lish orqali 2 ning N-darajasiga bo'ladi.", '64 >> 2 natijasi: 16'), (123, "Ikkilik (binary) sanoq sistemasidan o'nlikka o'tkazish", "Binar satrni o'nlik butun songa aylantiring.", '#!/usr/bin/env bash\n\nbin_str="101010"\ndec_val=$((2#$bin_str))\n\necho "Binar $bin_str o\'nlikda: $dec_val"\n', "Bash-da 'asos#qiymat' sintaksisi orqali har qanday 2 dan 64 gacha bo'lgan sanoq sistemasidagi sonlarni to'g'ridan-to'g'ri o'qish mumkin.", "Binar 101010 o'nlikda: 42"), (124, "Sakkizlik (octal) sanoq sistemasidan o'nlikka o'tkazish", "Linux fayl huquqlarining sakkizlik qiymatini (masalan 755) o'nlikka o'giring.", '#!/usr/bin/env bash\n\noct_perm="755"\ndec_perm=$((8#$oct_perm))\n\necho "Sakkizlik 0$oct_perm o\'nlikda: $dec_perm"\n', "'8#755' sakkizlik sanoq sistemasidagi qiymatni o'nlik ko'rinishga keltiradi.", "Sakkizlik 0755 o'nlikda: 493"), (125, "O'n oltilik (hex) sanoq sistemasidan o'nlikka o'tkazish", "Hexadecimal rang kodini o'nlik songa aylantiring.", '#!/usr/bin/env bash\n\nhex_color="FF"\ndec_color=$((16#$hex_color))\n\necho "Hex 0x$hex_color o\'nlikda: $dec_color"\n', "'16#FF' yoki '0xFF' sintaksisi 16-lik sanoq sistemasidagi qiymatni hisoblaydi.", "Hex 0xFF o'nlikda: 255"), (126, "Suzuvchi nuqtali hisoblash: 'bc' (Basic Calculator)", "O'nlik kasrli sonlar bilan bo'lish amalini 'bc' orqali bajaring.", '#!/usr/bin/env bash\n\ncalc=$(echo "scale=2; 22 / 7" | bc)\necho "Pi yaqinlashishi: $calc"\n', "Bash o'zida faqat butun sonlar arifmetikasini qo'llab-quvvatlaydi. O'nlik kasrlar bilan aniq ishlash uchun standart 'bc' utilitasidan foydalaniladi.", 'Pi yaqinlashishi: 3.14'), (127, "'bc' da 'scale' parametri bilan aniqlikni sozlash", 'Hisob-kitob natijasini verguldan keyin 4 xonali aniqlikda oling.', '#!/usr/bin/env bash\n\nresult=$(bc <<< "scale=4; 100 / 3")\necho "Aniqlik 4 xona: $result"\n', "'scale=N' direktivasi 'bc' ga natijadagi o'nlik raqamlar sonini N ta qilib belgilashni buyuradi.", 'Aniqlik 4 xona: 33.3333'), (128, "'bc -l' orqali matematik funksiyalardan foydalanish", 'Kvadrat ildiz (sqrt) qiymatini hisoblang.', '#!/usr/bin/env bash\n\nroot=$(echo "scale=2; sqrt(144)" | bc -l)\necho "144 ning kvadrat ildizi: $root"\n', "'bc -l' matematik standart kutubxonani yuklaydi, unda 'sqrt' (ildiz), 's()' (sinus), 'c()' (kosinus), 'l()' (natural logarifm) mavjud.", '144 ning kvadrat ildizi: 12.00'), (129, "Suzuvchi nuqtali sonlarni 'bc' orqali taqqoslash", "Ikki o'nlik kasr sonning kattasini tekshiring.", '#!/usr/bin/env bash\n\nval1="14.85"\nval2="14.90"\n\nis_greater=$(echo "$val1 > $val2" | bc)\nif [ "$is_greater" -eq 1 ]; then\n    echo "$val1 katta"\nelse\n    echo "$val2 katta yoki teng"\nfi\n', "'bc' taqqoslash amallarida rost bo'lsa 1, yolg'on bo'lsa 0 qaytaradi.", '14.90 katta yoki teng'), (130, "'awk' yordamida suzuvchi nuqtali hisob-kitoblar", "Server xotirasi nisbatini 'awk' da hisoblab chiqaring.", '#!/usr/bin/env bash\n\ntotal=16384\nused=9850\n\npercentage=$(awk -v t=$total -v u=$used \'BEGIN { printf "%.2f", (u / t) * 100 }\')\necho "Xotira bandligi: $percentage%"\n', "'awk' mustaqil dasturlash tili bo'lib, C kabi suzuvchi nuqta (double) bilan ajoyib va tez ishlaydi.", 'Xotira bandligi: 60.12%'), (131, "Tasodifiy son olish: '$RANDOM'", 'Bash-ning ichki tasodifiy son generatoridan foydalaning.', '#!/usr/bin/env bash\n\nraw_rnd=$RANDOM\necho "Tasodifiy son (0-32767): $raw_rnd"\n', "'$RANDOM' har safar murojaat qilinganda 0 dan 32767 gacha bo'lgan tasodifiy butun sonni qaytaradi.", 'Tasodifiy son (0-32767): 18452'), (132, 'Muayyan oraliqda tasodifiy son yaratish (1 dan N gacha)', 'Zar toshi kabi 1 dan 6 gacha tasodifiy son hosil qiling.', '#!/usr/bin/env bash\n\ndice=$(( (RANDOM % 6) + 1 ))\necho "Zar toshi natijasi: $dice"\n', "'$(( (RANDOM % N) + MIN ))' formulasi yordamida ixtiyoriy oraliqdagi tasodifiy butun sonlar olinadi.", 'Zar toshi natijasi: 4'), (133, 'Tasodifiy tarmoq portini tanlash (1024 - 65535)', 'Foydalanilmagan tasodifiy yuqori port raqamini generatsiya qiling.', '#!/usr/bin/env bash\n\nport=$(( 1024 + (RANDOM % (65535 - 1024 + 1)) ))\necho "Generatsiya qilingan port: $port"\n', "Xavfsiz dinamik portlar oralig'idan (1024-65535) tasodifiy port tanlash orqali parallel testlar to'qnashuvining oldi olinadi.", 'Generatsiya qilingan port: 48921'), (134, 'Sekundlarni soat, daqiqa va sekundlarga aylantirish', 'Server ishlash vaqtini (uptime) odam tushunadigan formatga keltiring.', '#!/usr/bin/env bash\n\ntotal_sec=3665\n\nhours=$((total_sec / 3600))\nrem=$((total_sec % 3600))\nminutes=$((rem / 60))\nseconds=$((rem % 60))\n\nprintf "%02d:%02d:%02d\\n" "$hours" "$minutes" "$seconds"\n', "Arifmetik bo'lish va qoldiq olish operatorlari orqali vaqtni birliklarga ajratish sodda va samarali amalga oshadi.", '01:01:05'), (135, 'Baytlarni Megabaytga aylantirish', "Fayl hajmini baytlardan MB ga o'tkazib, qoldig'ini hisoblang.", '#!/usr/bin/env bash\n\nbytes=104857600\nmb=$((bytes / (1024 * 1024)))\n\necho "Hajmi: ${mb} MB"\n', "Xotira o'lchov birliklari $1024$ asosida hisoblanadi ($1\\text{ MB} = 1024 \\times 1024\\text{ bayt}$).", 'Hajmi: 100 MB'), (136, 'Faktorial hisoblash (iterativ usulda)', "5 sonining faktorialini ($5!$) for sikli va arifmetik ko'paytirish bilan toping.", '#!/usr/bin/env bash\n\nn=5\nfact=1\n\nfor (( i=1; i<=n; i++ )); do\n    fact=$((fact * i))\ndone\n\necho "$n! = $fact"\n', "Faktorial algoritmi har bir qadamda yangi qiymatni oldingi yig'indiga ko'paytirib boradi.", '5! = 120'), (137, 'Fibonachchi sonlar ketma-ketligi', 'Dastlabki 7 ta Fibonachchi sonini chop eting.', '#!/usr/bin/env bash\n\na=0\nb=1\necho -n "$a $b "\n\nfor (( i=2; i<7; i++ )); do\n    c=$((a + b))\n    echo -n "$c "\n    a=$b\n    b=$c\ndone\necho ""\n', "Fibonachchi ketma-ketligida har bir yangi element o'zidan oldingi ikkita elementning arifmetik yig'indisiga teng bo'ladi.", '0 1 1 2 3 5 8'), (138, "Eng katta umumiy bo'luvchi (EKUB / GCD)", 'Evklid algoritmi orqali 48 va 18 ning EKUB ini toping.', '#!/usr/bin/env bash\n\nx=48\ny=18\n\nwhile (( y != 0 )); do\n    r=$((x % y))\n    x=$y\n    y=$r\ndone\n\necho "EKUB: $x"\n', "Evklid algoritmi qoldiq nolga teng bo'lguncha doimiy modul amalini bajarish orqali eng katta bo'luvchini tezkor topadi.", 'EKUB: 6'), (139, 'Eng kichik umumiy karrali (EKUK / LCM)', 'EKUB orqali 12 va 15 ning EKUK ini hisoblang: $(a \\times b) / \\text{EKUB}$.', '#!/usr/bin/env bash\n\na=12\nb=15\n# a va b ning EKUBi 3 ga teng\ngcd=3\nlcm=$(( (a * b) / gcd ))\n\necho "EKUK: $lcm"\n', "Ikkita sonning ko'paytmasini ularning EKUBiga bo'lish orqali ularning EKUKi topiladi.", 'EKUK: 60'), (140, 'Sonning tub (prime) ekanligini tekshirish', "29 sonining tub ekanligini arifmetik bo'linish orqali aniqlang.", '#!/usr/bin/env bash\n\nn=29\nis_prime=1\n\nfor (( i=2; i*i<=n; i++ )); do\n    if (( n % i == 0 )); then\n        is_prime=0\n        break\n    fi\ndone\n\necho "$n soni tubmi: $( (( is_prime )) && echo \'Ha\' || echo \'Yoq\' )"\n', "Son faqat 1 ga va o'ziga bo'linsa tub son hisoblanadi. Tekshirishni $\\sqrt{n}$ gacha davom ettirish optimaldir.", '29 soni tubmi: Ha'), (141, "Raqamlar yig'indisini hisoblash", "Butun sonning har bir raqamini ajratib olib, ularning yig'indisini hisoblang.", '#!/usr/bin/env bash\n\nnum=12345\nsum=0\n\nwhile (( num > 0 )); do\n    digit=$((num % 10))\n    sum=$((sum + digit))\n    num=$((num / 10))\ndone\n\necho "Raqamlar yig\'indisi: $sum"\n', "10 ga bo'lgandagi qoldiq eng oxirgi raqamni beradi, 10 ga butunli bo'lish esa oxirgi raqamni o'chiradi.", "Raqamlar yig'indisi: 15"), (142, 'Haroratni Selsiy dan Farengeyt ga aylantirish', '25 daraja Selsiy haroratini Farengeyt formulasida hisoblang ($F = C \\times 9/5 + 32$).', '#!/usr/bin/env bash\n\ncelsius=25\nfahr=$(echo "scale=1; ($celsius * 9 / 5) + 32" | bc)\n\necho "$celsius°C = ${fahr}°F"\n', "O'nlik kasrli standart harorat konvertatsiyasi 'bc' orqali hisoblanadi.", '25°C = 77.0°F'), (143, 'Valyuta konvertatsiyasi va tranzaksiya komissiyasi', "Pul o'tkazmasidan 1.5% komissiya ushlab qolinishini hisoblang.", '#!/usr/bin/env bash\n\namount=1000\nfee_percent=1.5\n\nnet_amount=$(awk -v a=$amount -v f=$fee_percent \'BEGIN { fee = (a * f) / 100; printf "%.2f", a - fee }\')\necho "Sof mablag\': $net_amount USD"\n', "'awk' orqali foiz va qolgan summani aniq hisoblash.", "Sof mablag': 985.00 USD"), (144, "Massiv elementlari o'rtacha arifmetik qiymatini hisoblash", "5 ta server ping vaqtlarining o'rtacha qiymatini toping.", '#!/usr/bin/env bash\n\npings=(12 15 18 11 14)\nsum=0\n\nfor p in "${pings[@]}"; do\n    sum=$((sum + p))\ndone\n\navg=$((sum / ${#pings[@]}))\necho "O\'rtacha ping: ${avg}ms"\n', "Barcha elementlar yig'indisini elementlar soniga bo'lish orqali butun o'rtacha qiymat topiladi.", "O'rtacha ping: 14ms"), (145, "Sonni 16-lik (hex) formatga o'tkazish", "O'nlik sonni toza arifmetik orqali hex satrga formatlang.", '#!/usr/bin/env bash\n\ndec=48879\nprintf "0x%X\\n" "$dec"\n', "'printf' ning '%X' formati sonni darhol katta harfli hex ko'rinishida chop etadi.", '0xBEEF'), (146, "Bitmask orqali binar ko'rinishni chop etish", '8-bitli sonning har bir bitini alohida ekranga chiqaring.', '#!/usr/bin/env bash\n\nval=42\nbin=""\n\nfor (( i=7; i>=0; i-- )); do\n    bit=$(( (val >> i) & 1 ))\n    bin="${bin}${bit}"\ndone\n\necho "42 ning 8-bitli binar shakli: $bin"\n', "Bitlarni o'ngga N ta surib '& 1' qilish orqali har bir bitning 0 yoki 1 ekanligi aniqlanadi.", '42 ning 8-bitli binar shakli: 00101010'), (147, 'Xotira sahifalari sonini hisoblash (Page size = 4KB)', "64 MB bufer xotirasiga nechta 4096 baytlik sahifa sig'ishini hisoblang.", '#!/usr/bin/env bash\n\nbuffer_bytes=$((64 * 1024 * 1024))\npage_size=4096\npages=$((buffer_bytes / page_size))\n\necho "Sahifalar soni: $pages ta"\n', "Tizimli dasturlash va operatsion tizimlarda xotira sahifalari (paging) miqdori butun bo'lish orqali aniqlanadi.", 'Sahifalar soni: 16384 ta'), (148, "Daraja o'sish vaqtini o'lchash (Exponential Backoff kalkulyatori)", 'Qayta urinish (retry) algoritmi uchun eksponentsial kutish vaqtini hisoblang: $2^{\\text{attempt}}$.', '#!/usr/bin/env bash\n\nattempt=4\nbase_delay=2\ndelay=$(( base_delay * (2 ** attempt) ))\n\necho "$attempt-urinish uchun kutish vaqti: ${delay}s"\n', 'Eksponentsial orqaga chekinish (exponential backoff) tarmoq nosozliklarida serverni ortiqcha yuklamaslik uchun kutish vaqtini 2 barobardan oshirib boradi.', '4-urinish uchun kutish vaqti: 32s'), (149, 'IP manzilni butun 32-bitli songa aylantirish (IPv4 to Integer)', "IPv4 manzilini 32-bitli butun songa (numeric IP) o'giring.", '#!/usr/bin/env bash\n\nip="192.168.1.1"\nIFS=\'.\' read -r o1 o2 o3 o4 <<< "$ip"\n\nint_ip=$(( (o1 << 24) + (o2 << 16) + (o3 << 8) + o4 ))\necho "$ip butun son ko\'rinishida: $int_ip"\n', "IPv4 manzili 4 ta oktetdan iborat. Har bir oktet tegishli ravishda 24, 16, 8 bit chapga surilib qo'shilsa, yagona 32-bitli integer hosil bo'ladi.", "192.168.1.1 butun son ko'rinishida: 3232235777"), (150, 'Kompleks resurs balansi kalkulyatori: Klaster quvvat hisoblagichi', "Klasterdagi serverlar soni, protsessor va xotira zaxirasini tahlil qiluvchi to'liq hisobot tuzing.", '#!/usr/bin/env bash\n\nnodes=8\nram_per_node=64\ncpu_per_node=16\n\ntotal_ram=$((nodes * ram_per_node))\ntotal_cpu=$((nodes * cpu_per_node))\n\nreserved_ram=$(( (total_ram * 20) / 100 ))\navailable_ram=$((total_ram - reserved_ram))\n\necho "=== Klaster Resurslari Hisoboti ==="\necho "Tugunlar: $nodes ta"\necho "Jami CPU: $total_cpu vCPU"\necho "Jami RAM: ${total_ram} GB"\necho "Zaxiralangan (20%): ${reserved_ram} GB"\necho "Foydalanishga ochiq RAM: ${available_ram} GB"\n', "Bash arifmetikasi va parameter expansion imkoniyatlari yordamida tashqi dasturlarsiz to'liq va tezkor server sig'imi hisobotlarini tuzish mumkin.", '=== Klaster Resurslari Hisoboti ===\nTugunlar: 8 ta\nJami CPU: 128 vCPU\nJami RAM: 512 GB\nZaxiralangan (20%): 102 GB\nFoydalanishga ochiq RAM: 410 GB')]

